use crate::store::{migrate, run};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Lock {
    pub pin_hash: String,
    pub generation: u64,
}

impl Lock {
    pub fn is_locked(&self) -> bool {
        !self.pin_hash.is_empty()
    }
